def choose_move(observation):
    def _pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def _dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def _step(src, dst):
        dx = 0 if dst[0] == src[0] else (1 if dst[0] > src[0] else -1)
        dy = 0 if dst[1] == src[1] else (1 if dst[1] > src[1] else -1)
        if dx < -1:
            dx = -1
        elif dx > 1:
            dx = 1
        if dy < -1:
            dy = -1
        elif dy > 1:
            dy = 1
        return [dx, dy]

    env = observation.get("environment_name", "resource_collection")
    sx, sy = _pos(observation.get("self_position"))
    ox, oy = _pos(observation.get("opponent_position"), (sx, sy))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)
    gw = observation.get("grid_width", 0)
    gh = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return _step(self_pos, opp_pos)
        corners = [(0, 0), (0, max(0, gh - 1)), (max(0, gw - 1), 0), (max(0, gw - 1), max(0, gh - 1))]
        target = corners[0]
        best = -1
        for c in corners:
            d = _dist(c, opp_pos)
            if d > best:
                best = d
                target = c
        return _step(self_pos, target)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("enemy_territory") or []
        best = None
        best_d = None
        for item in targets:
            p = _pos(item, None)
            if p is None:
                continue
            d = _dist(self_pos, p)
            if best is None or d < best_d:
                best = p
                best_d = d
        if best is not None:
            return _step(self_pos, best)
        # fallback: move toward center if known, else toward opponent
        if gw and gh:
            return _step(self_pos, (gw // 2, gh // 2))
        return _step(self_pos, opp_pos)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    best = None
    best_d = None
    for item in resources:
        p = _pos(item, None)
        if p is None:
            continue
        d = _dist(self_pos, p)
        if best is None or d < best_d:
            best = p
            best_d = d
    if best is not None:
        return _step(self_pos, best)

    # Generic fallback: pressure opponent if nothing else is visible.
    return _step(self_pos, opp_pos)

